  "statement": "CREATE OR REPLACE TABLE workspace.mlpab3b210e.stg_user_emb AS SELECT user_id, CAST(e1 AS DOUBLE) e1, CAST(e2 AS DOUBLE) e2, CAST(e3 AS DOUBLE) e3, CAST(e4 AS DOUBLE) e4, CAST(e5 AS DOUBLE) e5, CAST(e6 AS DOUBLE) e6, CAST(e7 AS DOUBLE) e7, CAST(e8 AS DOUBLE) e8 FROM read_files('/Volumes/workspace/mlpab3b210e/recs_data/user_embeddings.csv', format => 'csv', header => true)"
}

{
  "warehouse_id": "4dfab06c923fe3cc",
