  "statement": "CREATE OR REPLACE TABLE workspace.mlpab3b210e.stg_interactions AS SELECT user_id, item_id FROM read_files('/Volumes/workspace/mlpab3b210e/recs_data/interactions.csv', format => 'csv', header => true)"
}

{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "CREATE OR REPLACE TABLE workspace.mlpab3b210e.recs2ead15 (rec_id STRING NOT NULL, user_id STRING, rank INT, item_id STRING, CONSTRAINT recs2ead15_pk PRIMARY KEY (rec_id)) TBLPROPERTIES (delta.enableChangeDataFeed = true)"
}

{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "INSERT INTO workspace.mlpab3b210e.recs2ead15 WITH scores AS (SELECT u.user_id AS user_id, i.item_id AS item_id, (u.e1*i.e1 + u.e2*i.e2 + u.e3*i.e3 + u.e4*i.e4 + u.e5*i.e5 + u.e6*i.e6 + u.e7*i.e7 + u.e8*i.e8) AS score FROM workspace.mlpab3b210e.stg_user_emb u CROSS JOIN workspace.mlpab3b210e.stg_item_emb i WHERE NOT EXISTS (SELECT 1 FROM workspace.mlpab3b210e.stg_interactions x WHERE x.user_id = u.user_id AND x.item_id = i.item_id)), ranked AS (SELECT user_id, item_id, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY score DESC, item_id ASC) AS rnk FROM scores) SELECT concat(user_id, '#', CAST(rnk AS STRING)) AS rec_id, user_id, CAST(rnk AS INT) AS rank, item_id FROM ranked WHERE rnk <= 5"
}

{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "SELECT (SELECT COUNT(*) FROM workspace.mlpab3b210e.recs2ead15) AS total_rows, (SELECT COUNT(DISTINCT user_id) FROM workspace.mlpab3b210e.recs2ead15) AS users, (SELECT COUNT(*) FROM (SELECT user_id FROM workspace.mlpab3b210e.recs2ead15 GROUP BY user_id HAVING COUNT(*) <> 5)) AS bad_users, (SELECT COUNT(DISTINCT rec_id) FROM workspace.mlpab3b210e.recs2ead15) AS distinct_keys"
}

{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "SELECT r.rec_id, r.user_id, r.rank, r.item_id, (SELECT COUNT(*) FROM workspace.mlpab3b210e.stg_interactions x WHERE x.user_id=r.user_id AND x.item_id=r.item_id) AS was_interacted FROM workspace.mlpab3b210e.recs2ead15 r WHERE r.user_id='U0003' ORDER BY r.rank"
}
